// LDP Table / layer 'Layer 1' / frame 2
void frame_9704_1(Activation& scope) {
    stop();
    //
    scope["oldpage"] = _root["Page"];
    _root["Page"] = Math["min"](scope["_parent"]["TotalPages"] - 1, _root["Page"]);
    if (scope["oldpage"] != _root["Page"]) {
        // if the page is already past the max.. refresh and load the last page
        if (isNaN(_root["Page"])) {
            _root["Page"] = 1;
        }
        prevFrame();
    }
    //
    scope["pagebox"]["text"] = (_root["Page"] + 1) + "/" + scope["_parent"]["TotalPages"];
    scope["highlighted"] = "";
    scope["_parent"]["Selected"] = "";
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        for (scope["i"] = 0; scope["i"] < scope["Results"]["length"] - 1; scope["i"]++) {
            scope.self["Row" + scope["i"]]["gotoAndStop"](1);
            //this["Row"+highlighted].filters = [];
        }
        scope["highlighted"] = Math["round"](scope["_ymouse"] / 20);
        if (scope["highlighted"] >= 0 && scope["highlighted"] <= scope["Results"]["length"] - 1) {
            scope.self["Row" + scope["highlighted"]]["gotoAndStop"](2);
        }
        if (scope["_parent"]["Selected"] >= 0 && scope["_parent"]["Selected"] <= scope["Results"]["length"] - 1) {
            scope.self["Row" + scope["_parent"]["Selected"]]["gotoAndStop"](3);
        }
        return undefined;
    });
    scope["onMouseDown"] = scope.function([](Activation& scope) -> Value {
        scope["_parent"]["Selected"] = "";
        scope["select"] = Math["round"](scope["_ymouse"] / 20);
        if (scope["select"] >= 0 && scope["select"] <= scope["Results"]["length"] - 2) {
            scope["_parent"]["Selected"] = Math["round"](scope["_ymouse"] / 20);
        }
        return undefined;
    });
    scope["Refresh"] = scope.function([](Activation& scope) -> Value {
        _root["Page"] = Math["max"](_root["Page"], 0);
        for (scope["i"] = 0; scope["i"] < scope["Results"]["length"] - 1; scope["i"]++) {
            scope.self["Row" + scope["i"]]["removeMovieClip"]();
        }
        prevFrame();
        return undefined;
    });
}

